	(8494, 47, 'الموسيقى تساعدني على التركيز عندما أدرس.', 'Ders çalışırken müzik odaklanmama yardımcı oluyor.', 10, 14, '2026-07-21 15:01:10', '2026-07-21 15:01:10', 649, 1, 1, NULL),
